descriptor.templateCss:
.excel-grid-container {
    background-color: #ffffff;
    width: 100%;
    height: 100%;
    display: flex;
    flex-direction: column;
    font-family: 'Roboto', sans-serif;
    color: #333;
}

.grid-header {
    display: flex;
    justify-content: space-between; 
    align-items: center;
    padding: 10px 16px;
    background-color: #f5f7fa;
    border-bottom: 2px solid #cfd8dc;
    flex-wrap: wrap; 
    gap: 10px;
}

.legend-container {
    display: flex;
    gap: 15px;
    font-size: 13px;
    font-weight: 500;
    color: #455a64;
}

.legend-item { display: flex; align-items: center; gap: 6px; }
.color-box { width: 12px; height: 12px; border-radius: 2px; }

.date-picker-container {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 14px;
    font-weight: 500;
    color: #455a64;
    margin-right: 50px;
}

.form-control-date {
    padding: 6px 10px;
    font-size: 14px;
    border: 1px solid #cfd8dc;
    border-radius: 4px;
    outline: none;
    color: #455a64;
    cursor: pointer;
    font-family: inherit;
    background-color: #ffffff;
}

.form-control-date:focus { border-color: #607d8b; }

.table-wrapper {
    flex-grow: 1;
    overflow: auto;
}

table {
    border-collapse: collapse;
    width: 100%;
    min-width: max-content;
    margin-bottom: 40px; /* <--- ESTO ES LO ÚNICO QUE NECESITAS */
}

/* box-sizing border-box es vital para que los anchos fijos no se descuadren por los bordes */
th, td {
    box-sizing: border-box; 
    border: 1px solid #cfd8dc;
    padding: 4px 2px;
    text-align: center;
    font-size: 12px;
    min-width: 32px;
    height: 25px;
}

/* --- COLUMNAS CONGELADAS (Estilo Excel) --- */
.col-fixed-1 { position: sticky; left: 0; width: 65px; min-width: 65px; background-color: #eceff1; font-weight: bold; z-index: 20; }
.col-fixed-2 { position: sticky; left: 65px; width: 100px; min-width: 100px; background-color: #eceff1; font-weight: bold; z-index: 20; }
.col-fixed-3 { position: sticky; left: 165px; width: 160px; min-width: 160px; background-color: #eceff1; font-weight: bold; text-align: left; padding-left: 8px; z-index: 20; border-right: 2px solid #90a4ae; }

/* La cabecera superior */
th {
    background-color: #eceff1;
    color: #37474f;
    font-weight: bold;
    position: sticky;
    top: 0;
    z-index: 10;
}

/* Esquina superior izquierda inmovilizada doble (Arriba y a la izquierda) */
th.col-fixed-1, th.col-fixed-2, th.col-fixed-3 {
    z-index: 30;
}

.sum-col { background-color: #f1f8e9; font-weight: bold; vertical-align: middle; }

/* Clases solo para el texto */
.val-caudal { color: #1976d2; font-weight: 500; } 
.val-manual { color: #d32f2f; font-weight: bold; } 
.val-verde { color: #2e7d32; font-weight: bold; }

/* Clases exclusivas para los cuadraditos de la leyenda */
.box-caudal { background-color: #1976d2; }
.box-manual { background-color: #d32f2f; }

.filter-input {
    width: 100%;
    box-sizing: border-box;
    margin-top: 6px;
    font-size: 11px;
    padding: 3px 4px;
    border: 1px solid #90a4ae;
    border-radius: 3px;
    outline: none;
    font-family: inherit;
    font-weight: normal;
}

.filter-input:focus {
    border-color: #1976d2;
    box-shadow: 0 0 0 2px rgba(25, 118, 210, 0.2);
}

/* Desplegable de filtro (SECTOR): mismo look que .filter-input pero
   quitando la apariencia nativa del navegador y añadiendo una flechita propia */
.filter-select {
    width: 100%;
    box-sizing: border-box;
    margin-top: 6px;
    font-size: 11px;
    padding: 3px 18px 3px 4px;
    border: 1px solid #90a4ae;
    border-radius: 3px;
    outline: none;
    font-family: inherit;
    font-weight: normal;
    color: #37474f;
    background-color: #ffffff;
    cursor: pointer;

    /* Quitar flecha nativa del navegador */
    appearance: none;
    -webkit-appearance: none;
    -moz-appearance: none;

    /* Flecha propia, discreta, en SVG */
    background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='10' height='6' viewBox='0 0 10 6'><path d='M0 0L5 6L10 0Z' fill='%2390a4ae'/></svg>");
    background-repeat: no-repeat;
    background-position: right 5px center;
    background-size: 9px 6px;

    transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.filter-select:hover {
    border-color: #607d8b;
}

.filter-select:focus {
    border-color: #1976d2;
    box-shadow: 0 0 0 2px rgba(25, 118, 210, 0.2);
    background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='10' height='6' viewBox='0 0 10 6'><path d='M0 0L5 6L10 0Z' fill='%231976d2'/></svg>");
}

/* La opción "Todos" un poco más discreta, en cursiva, para diferenciarla del resto */
.filter-select option[value=""] {
    color: #78909c;
    font-style: italic;
}

/* Estilos para la columna de observaciones */
.obs-col {
    min-width: 150px;
    max-width: 250px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    background-color: #fffde7; /* Amarillo muy clarito para indicar que es editable */
    cursor: text;
    text-align: left;
    padding-left: 8px;
    color: #455a64;
    transition: background-color 0.3s;
}

.obs-col:hover {
    background-color: #fff59d; /* Amarillo más fuerte al pasar el ratón */
}

/* Input de edición en línea (estilo Excel) */
.obs-edit-input {
    width: 100%;
    box-sizing: border-box;
    border: none;
    background-color: #ffffff;
    font-family: inherit;
    font-size: 12px;
    color: #333;
    outline: 2px solid #1976d2; /* Borde azul al editar */
    padding: 2px 4px;
    border-radius: 2px;
}

descriptor.controllerScript:
self.onInit = function() {
    const $ctx = self.ctx;
    const $container = $ctx.$container; 
    
    const profileIdTarget = "d5cf5990-d4f4-11f0-9037-1d5f477d2d67";
    const $dateSelector = $container.find('#date-selector');
    
    let currentYear = new Date().getFullYear();
    let currentMonth = new Date().getMonth(); 
    let autoUpdateInterval;

    // --- CARGA DINÁMICA DE EXCELJS ---
    // Antes, si el widget no tenía declarado el recurso exceljs.min.js en su
    // configuración, el botón solo mostraba un alert y nunca funcionaba, porque
    // ExcelJS nunca llegaba a existir. Ahora lo cargamos nosotros mismos aquí,
    // sin depender de esa configuración externa.
    function loadExcelJS(callback) {
        if (typeof ExcelJS !== 'undefined') {
            callback();
            return;
        }
        const existingScript = document.getElementById('exceljs-cdn-script');
        if (existingScript) {
            // Ya se está cargando (por ejemplo desde otro widget), esperamos a que termine
            const waitInterval = setInterval(() => {
                if (typeof ExcelJS !== 'undefined') {
                    clearInterval(waitInterval);
                    callback();
                }
            }, 150);
            return;
        }
        const script = document.createElement('script');
        script.id = 'exceljs-cdn-script';
        script.src = 'https://cdnjs.cloudflare.com/ajax/libs/exceljs/4.3.0/exceljs.min.js';
        script.onload = function() { callback(); };
        script.onerror = function() {
            alert('No se pudo cargar la librería de Excel (ExcelJS). Revisa tu conexión a internet.');
        };
        document.head.appendChild(script);
    }
    // Precargamos en cuanto arranca el widget, para que ya esté lista cuando se pulse el botón
    loadExcelJS(function() {});

    function setSelectorToCurrentMonth() {
        const yearStr = currentYear;
        const monthStr = ('0' + (currentMonth + 1)).slice(-2);
        $dateSelector.val(yearStr + '-' + monthStr);
    }

    $dateSelector.off('change').on('change', function() {
        const val = $(this).val(); 
        if (val) {
            const partes = val.split('-');
            const sYear = parseInt(partes[0]);
            if (sYear < 2000 || sYear > 2100) return;
            currentYear = sYear;
            currentMonth = parseInt(partes[1]) - 1; 
            renderGrid();
        }
    });

    // --- LÓGICA EXPORTAR EXCEL (.xlsx) ---
    $container.find('#btn-export-csv').off('click').on('click', function() {
        loadExcelJS(async function() {
            const wb = new ExcelJS.Workbook();
            const ws = wb.addWorksheet('Caudales');

            let headers = [];
            $container.find('#days-header-row th').each(function() {
                headers.push($(this).text().trim().replace(/(\r\n|\n|\r)/gm, " "));
            });
            const headerRow = ws.addRow(headers);

            headerRow.eachCell((cell) => {
                cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF2E7D32' } }; 
                cell.font = { color: { argb: 'FFFFFFFF' }, bold: true }; 
                cell.border = { 
                    top: {style:'thin'}, left: {style:'thin'}, 
                    bottom: {style:'thin'}, right: {style:'thin'} 
                };
            });

            $container.find('#assets-body tr').each(function() {
                if($(this).find('td').length === 1) return; 

                let rowData = [];
                $(this).find('td').each(function() {
                    let text = $(this).text().trim();
                    let textReplaced = text.replace(',', '.');
                    let isNumber = !isNaN(textReplaced) && text !== "";
                    rowData.push(isNumber ? Number(textReplaced) : text);
                });
                
                const dataRow = ws.addRow(rowData);
                dataRow.eachCell((cell) => {
                    cell.border = { 
                        top: {style:'thin'}, left: {style:'thin'}, 
                        bottom: {style:'thin'}, right: {style:'thin'} 
                    };
                });
            });

            const buffer = await wb.xlsx.writeBuffer();
            const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
            
            const mesStr = ('0' + (currentMonth + 1)).slice(-2);
            const fileName = `Calendario_caudales_${currentYear}_${mesStr}.xlsx`;
            
            const link = document.createElement("a");
            link.href = URL.createObjectURL(blob);
            link.download = fileName;
            link.click();
        });
    });
    // ---------------------------

    setTimeout(function() {
        setSelectorToCurrentMonth();
        renderGrid();
    }, 200);

    function renderGrid() {
        if (autoUpdateInterval) clearInterval(autoUpdateInterval);

        $container.find('#days-header-row').empty();
        $container.find('#assets-body').empty().append('<tr><td colspan="40" style="text-align:center; padding: 20px; font-weight: bold;">Cargando datos...</td></tr>');

        const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();
        const startTs = new Date(currentYear, currentMonth, 1).getTime();
        const endTs = new Date(currentYear, currentMonth + 1, 0, 23, 59, 59, 999).getTime();

        const urlDevices = '/api/user/devices?pageSize=5000&page=0&sortProperty=name&sortOrder=ASC';

        $ctx.http.get(urlDevices).subscribe(function(response) {
            if (response && response.data) {
                const targetDevices = response.data.filter(d => d.deviceProfileId && d.deviceProfileId.id === profileIdTarget);
                cargarAtributosYSort(targetDevices, startTs, endTs, daysInMonth);
            }
        });
    }

    function cargarAtributosYSort(devices, startTs, endTs, daysInMonth) {
        let completed = 0;
        
        if (devices.length === 0) {
            $ctx.$container.find('#assets-body').empty().append('<tr><td colspan="40" style="text-align:center; padding: 20px; color: #d32f2f;">No se han encontrado caudalímetros en este perfil. Verifica el ID.</td></tr>');
            return;
        }

        devices.forEach(function(device) {
            device.sector = 999999; 
            device.ha = 0; 
            
            const urlAttr = '/api/plugins/telemetry/DEVICE/' + device.id.id + '/values/attributes?keys=Sector,ha';
            
            $ctx.http.get(urlAttr).subscribe(function(data) {
                if (data) {
                    data.forEach(attr => {
                        if (attr.key === 'Sector') device.sector = parseFloat(attr.value) || attr.value;
                        if (attr.key === 'ha') device.ha = parseFloat(attr.value) || 0; 
                    });
                }
                if (++completed === devices.length) {
                    devices.sort((a, b) => {
                        const parseName = name => {
                            const parts = (name || '').replace(/[^\d-]/g, '').split('-').filter(Boolean);
                            return parts.map(p => parseInt(p, 10) || 0);
                        };
                        const pa = parseName(a.name), pb = parseName(b.name);
                        for (let i = 0; i < Math.max(pa.length, pb.length); i++) {
                            const diff = (pa[i] || 0) - (pb[i] || 0);
                            if (diff !== 0) return diff;
                        }
                        return 0;
                    });
                    buildEmptyTable(daysInMonth, devices);
                    cargarTelemetriaEnLotes(devices, startTs, endTs);
                }
            });
        });
    }

    // --- FILTROS ---
    // Sector: desplegable cerrado (select), no se puede escribir texto libre.
    // Caudalímetro: input de texto con datalist (se mantiene igual que antes).
    function applyFilters() {
        const fSector = $container.find('select[data-col="sector"]').val().toLowerCase().trim();
        const fCaudalimetro = $container.find('input[data-col="caudalimetro"]').val().toLowerCase().trim();

        $container.find('#assets-body tr').each(function() {
            const $tr = $(this);
            const vSector = $tr.find('td.col-fixed-1').text().toLowerCase().trim();
            const vCaudalimetro = $tr.find('td.col-fixed-2').text().toLowerCase();

            // Sector: coincidencia exacta (viene de un desplegable, no de texto libre)
            const sectorMatch = (fSector === '') || (vSector === fSector);

            if (sectorMatch && vCaudalimetro.includes(fCaudalimetro)) {
                $tr.show();
            } else {
                $tr.hide();
            }
        });
    }

    function buildEmptyTable(days, devices) {
        const $headerRow = $container.find('#days-header-row').empty();
        const $body = $container.find('#assets-body').empty();

        const uniqueSectors = [...new Set(devices.map(d => d.sector === 999999 ? '-' : d.sector))].sort((a, b) => a - b);
        const uniqueCaudalimetros = [...new Set(devices.map(d => d.name))].sort();

        // Filtro de texto libre con datalist (usado para CAUDALÍMETRO)
        const createTextFilter = (id, options) => {
            let html = `<br><input type="text" list="list-${id}" class="filter-input" data-col="${id}" placeholder="Filtrar...">`;
            html += `<datalist id="list-${id}">`;
            options.forEach(opt => html += `<option value="${opt}"></option>`);
            html += `</datalist>`;
            return html;
        };

        // Filtro tipo desplegable cerrado, sin posibilidad de escribir (usado para SECTOR)
        const createSelectFilter = (id, options) => {
            let html = `<br><select class="filter-select" data-col="${id}"><option value="">Todos</option>`;
            options.forEach(opt => html += `<option value="${opt}">${opt}</option>`);
            html += `</select>`;
            return html;
        };

        $headerRow.append('<th class="col-fixed-1">SECTOR' + createSelectFilter('sector', uniqueSectors) + '</th>');
        $headerRow.append('<th class="col-fixed-2">CAUDALÍMETRO' + createTextFilter('caudalimetro', uniqueCaudalimetros) + '</th>');
        
        for (let i = 1; i <= days; i++) $headerRow.append('<th>' + i + '</th>');
        
        $headerRow.append('<th>TOTAL</th>');
        $headerRow.append('<th style="background-color: #eceff1;">V<br><span style="font-weight:normal;font-size:10px;">(m3)</span></th>');
        $headerRow.append('<th style="background-color: #eceff1;">S<br><span style="font-weight:normal;font-size:10px;">(ha)</span></th>');
        $headerRow.append('<th style="background-color: #eceff1;">Consumo<br><span style="font-weight:normal;font-size:10px;">(m3 ha-1)</span></th>');
        $headerRow.append('<th>OBSERVACIONES</th>');
        
        $container.find('.filter-input').off('input').on('input', function() {
            applyFilters();
        });

        $container.find('.filter-select').off('change').on('change', function() {
            applyFilters();
        });

        devices.forEach(device => {
            let secDisplay = device.sector === 999999 ? '-' : device.sector;
            const displayName = device.label ? `${device.name} - ${device.label}` : device.name;

            let rowHtml = `<tr id="row-${device.id.id}" style="cursor:pointer;">
                <td class="col-fixed-1">${secDisplay}</td>
                <td class="col-fixed-2">${displayName}</td>`;
            
            for (let i = 1; i <= days; i++) {
                rowHtml += `<td id="cell-${device.id.id}-${i}" class="day-cell" data-day="${i}"></td>`;
            }
            
            rowHtml += `<td id="sum-total-${device.id.id}" class="sum-col val-caudal" style="font-weight:bold;">0</td>`;
            rowHtml += `<td id="vol-${device.id.id}">0</td>`;
            
            let displayHa = device.ha > 0 ? parseFloat(device.ha.toFixed(4)) : '0';
            rowHtml += `<td id="sup-${device.id.id}" style="background-color: #aed581; color: #333;">${displayHa}</td>`;
            
            rowHtml += `<td id="cons-${device.id.id}">0</td>`;
            rowHtml += `<td id="obs-${device.id.id}" class="obs-col" title="Click para editar"></td></tr>`;
            
            const $tr = $(rowHtml);
            
            $tr.on('click', function(e) {
                const $target = $(e.target).closest('td');

                if (!$target.hasClass('day-cell')) return;

                localStorage.removeItem('riego_ts');
                localStorage.removeItem('riego_caudal');
                localStorage.removeItem('riego_asset_id');
                localStorage.removeItem('riego_asset_name');
                localStorage.removeItem('riego_es_hoy');

                const diaClick = parseInt($target.attr('data-day'));
                const caudalClick = $target.text().trim();

                const hoy = new Date();
                const esHoy = (
                    diaClick === hoy.getDate() &&
                    currentMonth === hoy.getMonth() &&
                    currentYear === hoy.getFullYear()
                );

                if (!isNaN(diaClick)) {
                    let tsClick;
                    if (esHoy) {
                        tsClick = hoy.getTime();
                    } else {
                        tsClick = new Date(currentYear, currentMonth, diaClick, 12, 0, 0).getTime();
                    }

                    localStorage.setItem('riego_ts', tsClick);
                    localStorage.setItem('riego_caudal', caudalClick);
                    localStorage.setItem('riego_asset_id', device.id.id);
                    localStorage.setItem('riego_asset_name', device.name);
                    localStorage.setItem('riego_es_hoy', esHoy ? 'true' : 'false');
                }

                var targetEntityId = { entityType: 'DEVICE', id: device.id.id };

                if (esHoy) {
                    var descriptorsHoy = self.ctx.actionsApi.getActionDescriptors('row_click_today');
                    if (descriptorsHoy && descriptorsHoy.length > 0) {
                        descriptorsHoy.forEach(desc => self.ctx.actionsApi.handleWidgetAction(e, desc, targetEntityId, device.name, null, device.label || device.name));
                    } else {
                        var descriptors = self.ctx.actionsApi.getActionDescriptors('row_click');
                        if (descriptors) descriptors.forEach(desc => self.ctx.actionsApi.handleWidgetAction(e, desc, targetEntityId, device.name, null, device.label || device.name));
                    }
                } else {
                    var descriptors = self.ctx.actionsApi.getActionDescriptors('row_click');
                    if (descriptors) descriptors.forEach(desc => self.ctx.actionsApi.handleWidgetAction(e, desc, targetEntityId, device.name, null, device.label || device.name));
                }
            });

            $tr.find('.obs-col').on('click', function(e) {
                e.stopPropagation(); 
                const $cell = $(this);

                if ($cell.find('input').length > 0) return;

                const currentObs = $cell.text();
                const $input = $('<input type="text" class="obs-edit-input">');
                $input.val(currentObs);

                $cell.empty().append($input);
                $input.focus();

                function finishEdit(save) {
                    const newObs = $input.val().trim();
                    if (save && newObs !== currentObs) {
                        $cell.text("Guardando...");
                        const payload = { "observaciones": newObs };
                        $ctx.http.post(`/api/plugins/telemetry/DEVICE/${device.id.id}/timeseries/ANY`, payload).subscribe(
                            function() {
                                $cell.text(newObs).attr('title', newObs).css('background-color', '#c8e6c9'); 
                                setTimeout(() => $cell.css('background-color', ''), 1000);
                            },
                            function(err) {
                                alert("Error al guardar.");
                                $cell.text(currentObs);
                            }
                        );
                    } else {
                        $cell.text(currentObs);
                    }
                }

                $input.on('blur', function() { finishEdit(true); });
                $input.on('keydown', function(evt) {
                    if (evt.key === 'Enter') $input.blur(); 
                    else if (evt.key === 'Escape') finishEdit(false);
                });
            });

            $body.append($tr);
        });
    }

    function cargarTelemetriaEnLotes(devices, startTs, endTs) {
        let currentIndex = 0;
        const batchSize = 5; 
        function loadNextBatch() {
            if (currentIndex >= devices.length) {
                iniciarAutoUpdate(devices);
                return; 
            }
            let batch = devices.slice(currentIndex, currentIndex + batchSize);
            currentIndex += batchSize;
            let completed = 0;
            batch.forEach(device => {
               const url = `/api/plugins/telemetry/DEVICE/${device.id.id}/values/timeseries?keys=caudal_medio_diario,media_proyectada,observaciones&startTs=${startTs}&endTs=${endTs}&limit=10000`;
                $ctx.http.get(url).subscribe(function(data) {
                    procesarYpintar(data, device);
                    if (++completed === batch.length) loadNextBatch();
                });
            });
        }
        loadNextBatch();
    }

    function procesarYpintar(data, device) {
        let totalMensual = 0;
        const deviceId = device.id.id;
        const now = new Date();
        const todayDay = now.getDate();
        const isCurrentMonth = (currentYear === now.getFullYear() && currentMonth === now.getMonth());

        const valuesByDay = {};

        if (data.caudal_medio_diario) {
    data.caudal_medio_diario.forEach(item => {
        const day = new Date(item.ts).getDate();
        if (!valuesByDay[day]) valuesByDay[day] = {};
        if (!valuesByDay[day].caudalTs || item.ts > valuesByDay[day].caudalTs) {
            valuesByDay[day].caudal = item.value;
            valuesByDay[day].caudalTs = item.ts;
        }
    });
}
        if (data.media_proyectada) {
            data.media_proyectada.forEach(item => {
                const day = new Date(item.ts).getDate();
                if (!valuesByDay[day]) valuesByDay[day] = {};
                if (!valuesByDay[day].proyectadaTs || item.ts > valuesByDay[day].proyectadaTs) {
                    valuesByDay[day].proyectada = item.value;
                    valuesByDay[day].proyectadaTs = item.ts;
                }
            });
        }

        Object.keys(valuesByDay).forEach(dayStr => {
            const day = parseInt(dayStr);
            let valToDisplay = null;
            let cssClass = 'val-caudal';

            if (isCurrentMonth && day === todayDay) {
                valToDisplay = valuesByDay[day].proyectada;
                cssClass = 'val-verde';
            } else {
                valToDisplay = valuesByDay[day].caudal;
                cssClass = 'val-caudal';
            }

            if (valToDisplay !== null && valToDisplay !== undefined) {
                const val = Math.round(parseFloat(valToDisplay));
                if (val > 0) {
                    totalMensual += val;
                    $container.find(`#cell-${deviceId}-${day}`).html(`<div class="${cssClass}">${val}</div>`);
                }
            }
        });

        if (totalMensual > 0) {
            $container.find(`#sum-total-${deviceId}`).text(Math.round(totalMensual));
            const volumen = totalMensual * 86.4;
            $container.find(`#vol-${deviceId}`).text(volumen.toFixed(1));
            if (device.ha && device.ha > 0) {
                const consumo = Math.round(volumen / device.ha);
                $container.find(`#cons-${deviceId}`).text(consumo);
            }
        }

        if (data.observaciones && data.observaciones.length > 0) {
            data.observaciones.sort((a, b) => b.ts - a.ts);
            const latestObs = data.observaciones[0].value;
            $container.find(`#obs-${deviceId}`).text(latestObs).attr('title', latestObs);
        }
    }

    function iniciarAutoUpdate(devices) {
        const now = new Date();
        if (currentYear === now.getFullYear() && currentMonth === now.getMonth()) {
            actualizarDiaActual(devices);
            autoUpdateInterval = setInterval(() => actualizarDiaActual(devices), 60000);
        }
    }

    function actualizarDiaActual(devices) {
        const now = new Date();
        if (currentYear !== now.getFullYear() || currentMonth !== now.getMonth()) return;

        const todayDay = now.getDate();
        const currentTs = now.getTime();
        const startOfDay = new Date(now.getFullYear(), now.getMonth(), todayDay, 0, 0, 0).getTime();
        const endOfDay = new Date(now.getFullYear(), now.getMonth(), todayDay, 23, 59, 59, 999).getTime();

        let currentIndex = 0;
        const batchSize = 10;

        function processNextBatch() {
            if (currentIndex >= devices.length) return;
            let batch = devices.slice(currentIndex, currentIndex + batchSize);
            currentIndex += batchSize;
            let completed = 0;

            batch.forEach(device => {
                const url = `/api/plugins/telemetry/DEVICE/${device.id.id}/values/timeseries?keys=media_proyectada&startTs=${startOfDay}&endTs=${endOfDay}&limit=100`;
                $ctx.http.get(url).subscribe(function(data) {
                    if (data.media_proyectada && data.media_proyectada.length > 0) {
                        let actualVal = null, futureVal = null;
                        let latestActualTs = 0, latestFutureTs = 0;

                        data.media_proyectada.forEach(item => {
                            const val = Math.round(parseFloat(item.value));
                            if (val > 0) {
                                if (item.ts <= currentTs) {
                                    if (item.ts > latestActualTs) { latestActualTs = item.ts; actualVal = val; }
                                } else {
                                    if (item.ts > latestFutureTs) { latestFutureTs = item.ts; futureVal = val; }
                                }
                            }
                        });

                        const finalVal = (futureVal !== null) ? futureVal : actualVal;
                        if (finalVal !== null) {
                            $container.find(`#cell-${device.id.id}-${todayDay}`).html(`<div class="val-verde">${finalVal}</div>`);
                            recalcularTotales(device.id.id, device.ha);
                        }
                    }
                    if (++completed === batch.length) processNextBatch();
                }, function() { if (++completed === batch.length) processNextBatch(); });
            });
        }
        processNextBatch();
    }

    function recalcularTotales(deviceId, ha) {
        let totalMensual = 0;
        $container.find(`#row-${deviceId} .day-cell div`).each(function() {
            totalMensual += parseFloat($(this).text()) || 0;
        });
        $container.find(`#sum-total-${deviceId}`).text(Math.round(totalMensual));
        const volumen = totalMensual * 86.4;
        $container.find(`#vol-${deviceId}`).text(volumen.toFixed(1));
        if (ha && ha > 0) {
            $container.find(`#cons-${deviceId}`).text(Math.round(volumen / ha));
        }
    }

}; // FIN onInit

self.actionSources = function() {
    return { 
        'row_click': { name: 'Click en día pasado', multiple: true },
        'row_click_today': { name: 'Click en día actual', multiple: false }
    };
};

